import React, { useState } from "react";
import Swal from "sweetalert2";
import "bootstrap/dist/css/bootstrap.min.css";
import Plantilla from './plantilla_carga_gestiones.xlsx';
import config from './config';
import * as XLSX from "xlsx";
import { addDays } from "date-fns";

const App = () => {
  const [loaderVisible, setLoaderVisible] = useState(false);
  const [file, setFile] = useState(null);

  const getUrlParams = () => {
    const params = new URLSearchParams(window.location.search);
    const id = params.get("id");
    const campana = params.get("campana");

    if (!id || !campana) {
      throw new Error("Faltan parámetros en la URL.");
    }

    return { id, campana };
  };

  const handleTokenError = () => {
    localStorage.removeItem("token");
    Swal.fire("Error", "No estás autenticado. Por favor, inicia sesión.", "error").then(() => {
      window.location.href = "/";
    });
  };

  const decrypt = async (value) => {
    if (!value || value.trim() === "") {
      throw new Error("El valor encriptado está vacío o es inválido.");
    }

    const token = localStorage.getItem("token");
    console.log(token);
    if (!token) {
      handleTokenError();
      return;
    }

    const response = await fetch(`${config.API_BASE_URL}/decrypt`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ encrypted_value: value }),
    });

    if (response.status === 401) {
      handleTokenError();
      return;
    }

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Error al desencriptar: ${errorText}`);
    }

    const data = await response.json();
    if (!data.decrypted_value) {
      throw new Error("La API no devolvió un valor desencriptado.");
    }

    return data.decrypted_value;
  };

  const handleFileChange = (event) => {
    setFile(event.target.files[0]);
  };

  const handleDownloadTemplate = async () => {
    try {
      const token = localStorage.getItem("token");
      if (!token) {
        handleTokenError();
        return;
      }
  
      const urlParams = getUrlParams();
      const idCampana = await decrypt(urlParams.campana);

      // Consumir la API para obtener los valores del JSON de respuesta
      const response = await fetch(`${config.API_BASE_URL}/consulta-usuarios-carga-gestiones`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          id_campana: idCampana
        }),
      });
  
      if (!response.ok) {
        if (response.status === 401) {
          handleTokenError();
          return;
        }
        throw new Error(`Error al obtener datos: ${response.statusText}`);
      }
  
      const data = await response.json();

      if (!Array.isArray(data)) {
        throw new Error("La API no devolvió un arreglo válido.");
      }

      // Crear el archivo Excel con Plantilla
      const workbook = XLSX.utils.book_new();
  
      // Leer la plantilla original
      const responseTemplate = await fetch(Plantilla);
      const arrayBuffer = await responseTemplate.arrayBuffer();
      const originalWorkbook = XLSX.read(arrayBuffer, { type: "array" });
  
      // Clonar la primera hoja de la plantilla
      const firstSheet = originalWorkbook.Sheets[originalWorkbook.SheetNames[0]];
      XLSX.utils.book_append_sheet(workbook, firstSheet, "Hoja1");
  
    // Crear la segunda hoja con los datos de VALUE e ITEM
      const columnAData = data.map((item) => item.USERNAME); // Datos para la columna A
      const columnBData = data.map((item) => item.NOMBRE); // Datos para la columna B

      // Construir una matriz combinada para columnas A y B
      const combinedData = columnAData.map((value, index) => [value, columnBData[index] || ""]);

      // Crear la hoja con los datos combinados
      const worksheet = XLSX.utils.aoa_to_sheet(combinedData);
  
      XLSX.utils.book_append_sheet(workbook, worksheet, "Hoja2");
  
      // Generar archivo Excel
      const excelData = XLSX.write(workbook, { bookType: "xlsx", type: "array" });
  
      const blob = new Blob([excelData], { type: "application/octet-stream" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "plantilla_carga_gestiones.xlsx";
      link.click();
    } catch (error) {
      Swal.fire("Error", `No se pudo descargar la plantilla: ${error.message}`, "error");
    }
  };
  
  const renderErrorTable = (errores) => {
    const errorTable = document.createElement("table");
    errorTable.classList.add("table", "table-bordered", "mt-3");
  
    // Crear encabezados
    const headerRow = errorTable.insertRow();
    const headers = ["Fila", "Mensaje de Error"];
    headers.forEach((headerText) => {
      const th = document.createElement("th");
      th.textContent = headerText;
      headerRow.appendChild(th);
    });
  
    // Agregar filas de errores
    errores.forEach((error) => {
      const row = errorTable.insertRow();
      const cellFila = row.insertCell(0);
      const cellMensaje = row.insertCell(1);
  
      cellFila.textContent = error.fila;
      cellMensaje.textContent = error.mensaje;
    });
  
    const container = document.querySelector(".card-body");
    const existingTable = container.querySelector("table");
    if (existingTable) {
      existingTable.remove();
    }
    container.appendChild(errorTable);

  };

  const downloadErrorReport = (errores) => {
    const worksheet = XLSX.utils.json_to_sheet(errores);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Errores");
      
    // Generar archivo Excel
    const excelData = XLSX.write(workbook, { bookType: "xlsx", type: "array" });

    const blob = new Blob([excelData], { type: "application/octet-stream" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "reporte_errores_carga_campañas.xlsx";
    link.click();
  };
  
  const handleUploadFile = async () => {
    if (!file) {
      return Swal.fire("Error", "Debe seleccionar un archivo.", "error");
    }

    if (!file.name.match(/\.(xlsx)$/i)) {
      return Swal.fire("Error", "El archivo debe ser un archivo Excel (.xlsx).", "error");
    }
    
    setLoaderVisible(true);

    try {
      const token = localStorage.getItem("token");
      /*if (!token) {
        handleTokenError();
        return;
      }*/

      const urlParams = getUrlParams();
      const idCampana = await decrypt(urlParams.campana);
      const usuarioOperacion = await decrypt(urlParams.id);

      const reader = new FileReader();

      reader.onerror = () => {
        setLoaderVisible(false);
        Swal.fire("Error", "Ocurrió un problema al leer el archivo. Intente nuevamente.", "error");
      };
      
      reader.onload = async (event) => {
        const data = new Uint8Array(event.target.result);
        let workbook;

        try {
          workbook = XLSX.read(data, { type: "array" });
        } catch (error) {
          setLoaderVisible(false);
          Swal.fire("Error", "El archivo no es un Excel válido.", "error");
          return;
        }

        const sheetName = workbook.SheetNames[0];
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { header: 1 });

      
        if (!rows || rows.length <= 1) {
          setLoaderVisible(false);
          return Swal.fire("Error", "El archivo Excel no contiene filas de datos.", "error");
        }
      
        const dataRows = rows.slice(1).filter((row) =>
          row.some((cell) => cell !== null && cell !== undefined && cell.toString().trim() !== "")
        );
      
        if (dataRows.length === 0) {
          setLoaderVisible(false);
          return Swal.fire("Error", "El archivo Excel no contiene datos válidos.", "error");
        }
      
        // Arreglo para almacenar errores
        const errores = [];
      
        // Procesar cada fila
        for (let index = 0; index < dataRows.length; index++) {
          const row = dataRows[index];
          try {
            
            
            const body = {
              opcion: 1,
              //id_gestiones: parseInt(row[0], 10) || null,
              id_campana: parseInt(idCampana, 10) || null,
              id_deudor: parseInt(row[0], 10) || null,
              usuario: row[1]?.toString() || "Sin usuario",
              nombre: row[2]?.toString() || "Sin nombre",
              direccion_casa: row[3]?.toString() || "Sin dirección casa",
              direccion_trabajo: row[4]?.toString() || "Sin dirección trabajo",
              lugar_trabajo: row[5]?.toString() || "Sin lugar trabajo",
              email: row[6]?.toString() || "Sin email",
              nit: row[7]?.toString() || "Sin NIT",
              
              fecha_nacimiento: row[8] && !isNaN(row[8])
              ? addDays(new Date(0), (row[8] - 25569)).toISOString().split("T")[0]
              : null,

              //fecha_nacimiento: row[8],
            
              dpi: row[9]?.toString() || "Sin DPI",
              telefono_celular: row[10]?.toString() || "Sin teléfono celular",
              telefono_casa: row[11]?.toString() || "Sin teléfono casa",
              telefono_alterno: row[12]?.toString() || "Sin teléfono alterno",
              telefono_trabajo: row[13]?.toString() || "Sin teléfono trabajo",

              tipo_cuenta1: row[14]?.toString() || "",
              no_cuenta1: row[15]?.toString() || "",
              saldo1: parseFloat(row[16]) || 0,
              tipo_cuenta2: row[17]?.toString() || "",
              no_cuenta2: row[18]?.toString() || "",
              saldo2: parseFloat(row[19]) || 0,
              tipo_cuenta3: row[20]?.toString() || "",
              no_cuenta3: row[21]?.toString() || "",
              saldo3: parseFloat(row[22]) || 0,
              tipo_cuenta4: row[23]?.toString() || "",
              no_cuenta4: row[24]?.toString() || "",
              saldo4: parseFloat(row[25]) || 0,
              tipo_cuenta5: row[26]?.toString() || "",
              no_cuenta5: row[27]?.toString() || "",
              saldo5: parseFloat(row[28]) || 0,

              concepto1: row[29]?.toString() || "",
              descripcion1: row[30]?.toString() || "",
              concepto2: row[31]?.toString() || "",
              descripcion2: row[32]?.toString() || "",
              concepto3: row[33]?.toString() || "",
              descripcion3: row[34]?.toString() || "",
              concepto4: row[35]?.toString() || "",
              descripcion4: row[36]?.toString() || "",

              estado: true,
              usuario_operacion: parseInt(usuarioOperacion, 10) || null,
            };

            //document.getElementById("json-output").innerHTML += `
            //<h5>Fila ${index + 1}:</h5>
            //<pre>${JSON.stringify(body, null, 2)}</pre>
          //`;
          
      
            const response = await fetch(`${config.API_BASE_URL}/gestiones`, {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${token}`,
              },
              body: JSON.stringify(body),
            });
      
            if (!response.ok) {
              if (response.status === 401) {
                handleTokenError();
                return;
              }
              throw new Error(`Error en la carga: ${response.statusText}`);
            }
          } catch (e) {
            // Registrar errores
            const errorMessage = e.message || e.detail || ""; // Considerar mensaje en "detail" si está disponible
            if (errorMessage.includes("Invalid date of birth provided.")) {
              errores.push({
                fila: index + 2,
                mensaje: "La fecha de nacimiento no tiene un formato correcto."
              });
            } else if (errorMessage.includes("Assigned user is not available.")) {
              errores.push({
                fila: index + 2,
                mensaje: "Usuario asignado no está disponible."
              });
            } else if (errorMessage.includes("Fecha de nacimiento no tiene un formato de fecha válido")) {
              errores.push({
                fila: index + 2,
                mensaje: "La fecha de nacimiento no tiene un formato válido."
              });
            } else if (errorMessage.includes("Not Found")) {
              errores.push({
                fila: index + 2,
                mensaje: "Usuario asignado no está disponible."
              });
            } else {
              errores.push({
                fila: index + 2,
                mensaje: `Error inesperado: ${errorMessage}`
              });
            }
          }
          
        }
      
        setLoaderVisible(false);
      
        // Mostrar tabla de errores
        if (errores.length > 0) {
          renderErrorTable(errores);
          downloadErrorReport(errores);
          Swal.fire("Atención", "Algunas filas tienen errores. Por favor, verifica el reporte de errores.", "warning");
        } else  {
                  Swal.fire("Éxito", "Archivo procesado correctamente.", "success").then(() => {
                    // Redirigir a la pestaña deseada
                    const urlParams = getUrlParams();
                    window.location.href = `./carga_campanas?id=${urlParams.id}&campana=${urlParams.campana}`;
                  });
                }
      };
      

      reader.readAsArrayBuffer(file);
    } catch (error) {
      setLoaderVisible(false);
      Swal.fire("Error", error.message, "error");
    }
  };

  const handleBackToPanel = () => {
    const urlParams = getUrlParams();
    window.location.href = `./modulos?id=${urlParams.id}&campana=${urlParams.campana}`;
  };

  return (
    <div className="container mt-5">
      <div className="card">
        <div className="card-header text-center">
          <h4>Carga de Clientes</h4>
          <button className="btn btn-warning" onClick={handleBackToPanel}>
            Regresar al panel de módulos
          </button>
        </div>
        <div className="card-body">
          <div className="mb-3">
            <button className="btn btn-primary" onClick={handleDownloadTemplate}>
              Descargar Plantilla
            </button>
          </div>
          <form>
            <div className="mb-3">
              <label htmlFor="fileInput" className="form-label">
                Subir archivo Excel
              </label>
              <input type="file" className="form-control" id="fileInput" accept=".xlsx" onChange={handleFileChange} />
            </div>
            <button type="button" className="btn btn-success" onClick={handleUploadFile}>
              Cargar
            </button>

            {/*<div id="json-output" className="mt-3"></div>*/}
          </form>
          {loaderVisible && <div className="loader mt-3"></div>}
        </div>
      </div>
      

    </div>
  );
};

export default App;
